<div class="card form-card"><form method="post" action="?page=purchase&action=store"><?=$csrfField?><div class="form-grid"><label>Supplier<select name="supplier_id" required><option value="">Pilih supplier</option><?php foreach($suppliers as $s):?><option value="<?=$s['id']?>"><?=e($s['code'].' - '.$s['name'])?></option><?php endforeach;?></select></label><label>Gudang<select name="warehouse_id" required><option value="">Pilih gudang</option><?php foreach($warehouses as $w):?><option value="<?=$w['id']?>"><?=e($w['code'].' - '.$w['name'])?></option><?php endforeach;?></select></label><label>Tanggal<input type="date" name="po_date" value="<?=date('Y-m-d')?>" required></label><label>Status<select name="status"><option>Draft</option><option>Approved</option><option>Received</option></select></label><label class="full-field">Catatan<textarea name="notes"></textarea></label></div><h3>Detail Produk</h3><div class="table-wrap"><table id="detailTable"><thead><tr><th>Produk</th><th>Qty</th><th>Harga Beli</th><th>Aksi</th></tr></thead><tbody><tr><td><select name="product_id[]" required><option value="">Pilih produk</option><?php foreach($products as $p):?><option value="<?=$p['id']?>" data-price="<?=$p['purchase_price']?>"><?=e($p['code'].' - '.$p['name'])?></option><?php endforeach;?></select></td><td><input type="number" name="qty[]" min="0.01" step="0.01" required></td><td><input type="number" name="price[]" min="0" step="0.01" required></td><td><button type="button" class="btn btn-sm" onclick="this.closest('tr').remove()">Hapus</button></td></tr></tbody></table></div><button type="button" class="btn" onclick="addDetailRow('detailTable')">+ Tambah Produk</button><div class="form-actions"><a class="btn" href="?page=purchase">Batal</a><button class="btn btn-primary">Simpan PO</button></div></form></div>
<script>document.addEventListener('change',function(e){if(e.target.matches('select[name="product_id[]"]')){const p=e.target.selectedOptions[0]?.dataset.price||'';const input=e.target.closest('tr').querySelector('input[name="price[]"]');if(p)input.value=p;}});</script>
